<?php
use App\Application\Privacy\ConsentService;use App\Models\Party;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Validation\ValidationException;
uses(RefreshDatabase::class);
test('consent is versioned evidenced and withdrawable once',function(){$actor=User::factory()->create();$party=Party::create(['type'=>'PERSON','display_name'=>'Privacy Client','legal_identity'=>[],'status'=>'ACTIVE']);$service=app(ConsentService::class);$consent=$service->grant($party,null,'MARKETING','privacy-2026-01','WEB',['affirmed'=>true,'session'=>'test'],$actor);expect($consent->evidence_hash)->toHaveLength(64)->and($consent->events()->count())->toBe(1);$service->withdraw($consent,'CUSTOMER_REQUEST',['notes'=>'No longer wishes to receive offers'],$actor);expect($consent->refresh()->status)->toBe('WITHDRAWN')->and($consent->events()->count())->toBe(2);expect(fn()=>$service->withdraw($consent,'CUSTOMER_REQUEST',[],$actor))->toThrow(ValidationException::class);});
